<template>
  <div class="page-heal-task-list">
    <CrudToolbar :title="t('heal.tasks.title')" :can-create="false" />

    <el-tabs v-model="filters.tab" type="border-card">
      <el-tab-pane :label="t('heal.tasks.tabPending')" name="pending">
        <DataTable
          v-model:current-page="page"
          v-model:page-size="pageSize"
          :data="pendingTasks"
          :loading="pendingLoading"
          :server-side="true"
          :total="pendingTotal"
        >
          <el-table-column prop="task_id" :label="t('heal.tasks.taskId')" min-width="180" />
          <el-table-column prop="node_id" :label="t('common.node')" min-width="140" />
          <el-table-column prop="action_id" :label="t('heal.actionId')" min-width="160" />
          <el-table-column prop="risk_level" :label="t('heal.riskLevel')" width="100">
            <template #default="{ row }">
              <StatusTag :status="row.risk_level" type="default" />
            </template>
          </el-table-column>
          <el-table-column prop="created_at" :label="t('common.createdAt')" min-width="160">
            <template #default="{ row }">
              {{ formatTime(row.created_at) }}
            </template>
          </el-table-column>
          <el-table-column :label="t('common.actions')" width="260" fixed="right">
            <template #default="{ row }">
              <el-button
                v-if="authStore.isAdmin"
                link
                type="success"
                size="small"
                @click="onApprove(row, false)"
              >
                {{ t('heal.tasks.confirmExecute') }}
              </el-button>
              <el-button
                v-if="authStore.isAdmin"
                link
                type="primary"
                size="small"
                @click="onApprove(row, true)"
              >
                {{ t('heal.tasks.whitelistExecute') }}
              </el-button>
              <el-button
                v-if="authStore.isAdmin"
                link
                type="danger"
                size="small"
                @click="onReject(row)"
              >
                {{ t('common.reject') }}
              </el-button>
            </template>
          </el-table-column>
        </DataTable>
      </el-tab-pane>

      <el-tab-pane :label="t('heal.tasks.tabHistory')" name="history">
        <DataTable
          v-model:current-page="page"
          v-model:page-size="pageSize"
          :data="historyTasks"
          :loading="historyLoading"
          :server-side="true"
          :total="historyTotal"
        >
          <el-table-column prop="task_id" :label="t('heal.tasks.taskId')" min-width="180" />
          <el-table-column prop="node_id" :label="t('common.node')" min-width="140" />
          <el-table-column prop="action_id" :label="t('heal.actionId')" min-width="160" />
          <el-table-column prop="status" :label="t('common.status')" width="100">
            <template #default="{ row }">
              <StatusTag :status="row.status" type="task" />
            </template>
          </el-table-column>
          <el-table-column prop="risk_level" :label="t('heal.riskLevel')" width="100">
            <template #default="{ row }">
              <StatusTag :status="row.risk_level" type="default" />
            </template>
          </el-table-column>
          <el-table-column prop="created_at" :label="t('common.createdAt')" min-width="160">
            <template #default="{ row }">
              {{ formatTime(row.created_at) }}
            </template>
          </el-table-column>
          <el-table-column :label="t('common.actions')" width="120" fixed="right">
            <template #default="{ row }">
              <el-button
                v-if="authStore.isAdmin && (row.status === 'failed' || row.status === 'timeout')"
                link
                type="primary"
                size="small"
                @click="onRetry(row)"
              >
                {{ t('common.retry') }}
              </el-button>
            </template>
          </el-table-column>
        </DataTable>
      </el-tab-pane>
    </el-tabs>
  </div>
</template>

<script setup lang="ts">
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import {
  approvePendingTask,
  getHealTasks,
  getPendingTasks,
  rejectPendingTask,
  retryHealTask,
  type HealTaskRead,
} from '@/api/healTasks'
import { useRealtimeRefresh } from '@/composables/useRealtimeRefresh'
import { useListQuery } from '@/composables/useListQuery'
import StatusTag from '@/components/common/StatusTag.vue'
import DataTable from '@/components/common/DataTable.vue'
import CrudToolbar from '@/components/common/CrudToolbar.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()
const authStore = useAuthStore()

type HealTab = 'pending' | 'history'

const pendingTasks = ref<HealTaskRead[]>([])
const pendingTotal = ref(0)
const pendingLoading = ref(false)
const historyTasks = ref<HealTaskRead[]>([])
const historyTotal = ref(0)
const historyLoading = ref(false)

const { page, pageSize, filters } = useListQuery<{ tab: HealTab }>({
  defaults: { tab: 'pending' },
  parse: (q) => ({
    tab: (q.tab as HealTab) || 'pending',
  }),
  serialize: (f) => ({
    tab: f.tab || undefined,
  }),
})

async function loadPending() {
  pendingLoading.value = true
  try {
    const response = await getPendingTasks({
      page: page.value,
      page_size: pageSize.value,
    })
    pendingTasks.value = response.items
    pendingTotal.value = response.total
  } catch (error) {
    showError(error, t('heal.tasks.loadPendingFailed'))
  } finally {
    pendingLoading.value = false
  }
}

async function loadHistory() {
  historyLoading.value = true
  try {
    const response = await getHealTasks({
      page: page.value,
      page_size: pageSize.value,
    })
    historyTasks.value = response.items
    historyTotal.value = response.total
  } catch (error) {
    showError(error, t('heal.tasks.loadHistoryFailed'))
  } finally {
    historyLoading.value = false
  }
}

async function loadActive() {
  if (filters.tab === 'pending') {
    await loadPending()
  } else {
    await loadHistory()
  }
}

// 切换 tab 时重置到第一页
watch(
  () => filters.tab,
  () => {
    page.value = 1
    loadActive()
  }
)

watch(
  () => ({ page: page.value, pageSize: pageSize.value }),
  loadActive,
  { deep: true, immediate: true }
)

async function onApprove(row: HealTaskRead, addToWhitelist: boolean) {
  try {
    await approvePendingTask(row.id, { add_to_whitelist: addToWhitelist })
    ElMessage.success(addToWhitelist ? t('heal.tasks.whitelistExecuted') : t('heal.tasks.taskConfirmed'))
    loadPending()
    loadHistory()
  } catch (error) {
    showError(error, t('heal.tasks.confirmFailed'))
  }
}

async function onReject(row: HealTaskRead) {
  try {
    const { value } = await ElMessageBox.prompt(t('common.rejectPrompt'), t('heal.tasks.rejectTitle'), {
      confirmButtonText: t('common.reject'),
      cancelButtonText: t('common.cancel'),
      inputType: 'textarea',
    })
    await rejectPendingTask(row.id, { reason: value })
    ElMessage.success(t('heal.tasks.taskRejected'))
    loadPending()
  } catch (error: any) {
    if (error === 'cancel') return
    showError(error, t('common.rejectFailed'))
  }
}

async function onRetry(row: HealTaskRead) {
  try {
    await retryHealTask(row.id)
    ElMessage.success(t('heal.tasks.retried'))
    loadHistory()
  } catch (error) {
    showError(error, t('heal.tasks.retryFailed'))
  }
}

function formatTime(value: string) {
  return new Date(value).toLocaleString()
}

useRealtimeRefresh(
  () => {
    loadPending()
    loadHistory()
  },
  ['heal'],
  { notifyEventTypes: ['heal.executed'] }
)
</script>
