import apiClient from './client'
import type { Page, PageParams } from './page'

export type HealTaskStatus = 'pending' | 'running' | 'success' | 'failed' | 'timeout' | 'cancelled'
export type HealTaskRiskLevel = 'low' | 'medium' | 'high'

export interface HealTaskRead {
  id: number
  task_id: string
  node_id: string
  alert_rule_id?: number | null
  heal_rule_id?: number | null
  action_id: string
  action_params: Record<string, unknown>
  status: HealTaskStatus
  risk_level: HealTaskRiskLevel
  requires_approval: boolean
  approved_by?: number | null
  approved_at?: string | null
  executed_by?: number | null
  started_at?: string | null
  finished_at?: string | null
  result?: Record<string, unknown> | null
  error_message?: string | null
  verification_config?: Record<string, unknown> | null
  verification_status?: string | null
  verification_result?: Record<string, unknown> | null
  verification_due_at?: string | null
  retry_count: number
  max_retries: number
  scheduled_at?: string | null
  created_at: string
  updated_at: string
}

export interface HealTaskListParams extends PageParams {
  node_id?: string
  status?: HealTaskStatus
}

export type PendingTaskListParams = PageParams

export interface ApprovePendingRequest {
  add_to_whitelist?: boolean
}

export interface RejectPendingRequest {
  reason?: string
}

export async function getHealTasks(params?: HealTaskListParams): Promise<Page<HealTaskRead>> {
  const response = await apiClient.get<Page<HealTaskRead>>('/v1/heal-tasks', { params })
  return response.data
}

export async function getPendingTasks(params?: PendingTaskListParams): Promise<Page<HealTaskRead>> {
  const response = await apiClient.get<Page<HealTaskRead>>('/v1/heal-pending-tasks', { params })
  return response.data
}

export async function approvePendingTask(
  taskId: number,
  data?: ApprovePendingRequest
): Promise<HealTaskRead> {
  const response = await apiClient.post<HealTaskRead>(
    `/v1/heal-pending-tasks/${taskId}/approve`,
    data || {}
  )
  return response.data
}

export async function rejectPendingTask(
  taskId: number,
  data?: RejectPendingRequest
): Promise<HealTaskRead> {
  const response = await apiClient.post<HealTaskRead>(
    `/v1/heal-pending-tasks/${taskId}/reject`,
    data || {}
  )
  return response.data
}

export async function retryHealTask(taskId: number): Promise<HealTaskRead> {
  const response = await apiClient.post<HealTaskRead>(`/v1/heal-tasks/${taskId}/retry`)
  return response.data
}
